/* eslint-disable react-hooks/exhaustive-deps */
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Button, Icon, Row, Col, Table, Empty, Input, Spin, Alert, message } from 'antd'
import React, { useEffect, useState } from 'react'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { RowWithMargin } from '../../../../EmployeeBenefits/CommonComponents'
import { ColTextAlignRight } from '../../../../EmployeeBenefits/CommonComponents/index.style'
import { useRoles } from '../../../state/hooks/useTeamContext'
import AddPermissionToRoleModal from './addPermission'
import { rolePermissionColumns } from './utility'

const { Search } = Input

const RolePermissions = ({ match, history }) => {
  const [addModalVisible, toggleAddModal] = useState(false)
  const [searchText, setSearchText] = useState(null)
  const { roleName } = match.params
  const { revokePermissionRequest, getGroupPermissions, groupPermissionsData } = useRoles()
  const [{ REVOKE_PERMISSION_ERROR, revokePermissionStatus, GROUP_PERMISSIONS_ERROR, groupPermissionsStatus }] = useErrorContextValue()
  const [{ REVOKE_PERMISSION_LOADER, GROUP_PERMISSIONS_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()

  const getFilteredData = () => {
    if (searchText) {
      return groupPermissionsData.filter(permission => new RegExp(searchText, 'i').test(permission.name) || new RegExp(searchText, 'i').test(permission.codename))
    }
    return groupPermissionsData
  }

  const handleRevokePermission = (permission) => {
    revokePermissionRequest({
      name: roleName,
      permissions: [permission]
    })
  }

  useEffect(() => {
    if (revokePermissionStatus === 'success') {
      message.success('Permission revoked successfully')
      getGroupPermissions({ group_name: roleName })
      resetError(['revokePermissionStatus'])
    }
  }, [revokePermissionStatus])

  useEffect(() => {
    getGroupPermissions({ group_name: roleName })
  }, [])

  return (
    <EbEmptyPage history={history}>
      <RowWithMargin type='flex' justify='space-between'>
        <Col span={14}>
          <h2>{roleName} - Permission List </h2>
        </Col>
        <Col span={6}>
          <Search
            placeholder='Search..'
            onChange={(e) => setSearchText(e.target.value)}
            disabled={GROUP_PERMISSIONS_ERROR || !Array.isArray(groupPermissionsData)}
          />
        </Col>
        <PermissionCheckerV2 requiredPermission='ops.can_perform_team_actions'>
          <ColTextAlignRight span={4}>
            <Button
              type='primary'
              onClick={() => toggleAddModal(true)}
            >
              Add Permission
              <Icon type='plus' />
            </Button>
          </ColTextAlignRight>
        </PermissionCheckerV2>
      </RowWithMargin>
      <Spin
        spinning={!!REVOKE_PERMISSION_LOADER || !!GROUP_PERMISSIONS_LOADER}
      >

        {(REVOKE_PERMISSION_ERROR) && <Alert type='error' message={revokePermissionStatus} banner />}
        {(GROUP_PERMISSIONS_ERROR) && <Alert type='error' message={groupPermissionsStatus} banner />}
        <Row>
          {
            !GROUP_PERMISSIONS_ERROR && Array.isArray(groupPermissionsData)
              ? (
                <Table
                  columns={rolePermissionColumns({ handleRevokePermission })}
                  dataSource={getFilteredData()}
                />
                )
              : <Empty />
          }
        </Row>
      </Spin>
      <AddPermissionToRoleModal
        visible={addModalVisible}
        toggleAddModal={toggleAddModal}
        roleName={roleName}
      />
    </EbEmptyPage>
  )
}
export default RolePermissions
