/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect } from 'react'
import { Modal, Form, Select, Alert, message, Spin } from 'antd'
import { useRoles } from '../../../state/hooks/useTeamContext'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'

const { Option } = Select

const AddPermissionToRoleModal = ({ visible, form, toggleAddModal, roleName, ...props }) => {
  const { getFieldDecorator } = form
  const { getPermissionList, permissionListData, addRolePermissionsRequest, getGroupPermissions, resetState } = useRoles()
  const [{ PERMISSION_LIST_ERROR, permissionListStatus, ADD_ROLE_PERMISSIONS_ERROR, addRolePermissionsStatus }] = useErrorContextValue()
  const [{ PERMISSION_LIST_LOADER, ADD_ROLE_PERMISSIONS_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()

  const handleOk = () => {
    form.validateFields((err, values) => {
      if (!err) {
        addRolePermissionsRequest({
          name: roleName,
          ...values
        })
      }
    })
  }

  useEffect(() => {
    if (addRolePermissionsStatus === 'success') {
      message.success('Permissions added successfully.')
      form.resetFields()
      toggleAddModal(false)
      getGroupPermissions({ group_name: roleName })
      resetState(['addRolePermissionsData'])
      resetError(['addRolePermissionsStatus'])
    }
  }, [addRolePermissionsStatus])

  useEffect(() => {
    getPermissionList()
  }, [getPermissionList])

  return (
    <Modal
      visible={visible}
      title='Grant New Permissions'
      okText='Grant'
      onCancel={() => toggleAddModal(false)}
      onOk={handleOk}
    >

      {(PERMISSION_LIST_ERROR) && <Alert type='error' message={permissionListStatus} banner />}
      {(ADD_ROLE_PERMISSIONS_ERROR) && <Alert type='error' message={addRolePermissionsStatus} banner />}
      <Spin spinning={!!PERMISSION_LIST_LOADER || !!ADD_ROLE_PERMISSIONS_LOADER}>
        <Form>
          <Form.Item
            label='Permissions'
          >
            {
              getFieldDecorator(
                'permissions'
              )(
                <Select
                  mode='multiple'
                  showArrow
                  optionFilterProp='children'
                  filterOption={(input, option) => (
                    option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0 ||
                    option.props.value.toLowerCase().indexOf(input.toLowerCase()) >= 0
                  )}
                >
                  {
                    !PERMISSION_LIST_ERROR && Array.isArray(permissionListData)
                      ? (
                          permissionListData.map(permission => (
                            <Option key={permission.codename} value={permission.codename}>{permission.name}</Option>
                          ))
                        )
                      : null
                  }
                  {
                    // TODO: filter permissions that are already there or disable them maybe.
                  }
                </Select>
              )
            }
          </Form.Item>
        </Form>

      </Spin>
    </Modal>
  )
}
export default Form.create({ name: 'grant-new-permission' })(AddPermissionToRoleModal)
